import { randomUUID } from "node:crypto";

export const addConflict = (state, conflict = {}) => {
  const existing = state.conflicts.find((item) => item.logicalPath === conflict.logicalPath && item.status === "unresolved");
  if (existing) { Object.assign(existing, conflict, { updatedAt: new Date().toISOString() }); return existing; }
  const value = { id: randomUUID(), status: "unresolved", createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), ...conflict };
  state.conflicts.push(value);
  return value;
};

export const resolveConflictRecord = (state, id, resolution) => {
  const value = state.conflicts.find((item) => item.id === id);
  if (!value) throw Object.assign(new Error("同步冲突不存在"), { code: "SYNC_CONFLICT_NOT_FOUND" });
  value.status = "resolved";
  value.resolution = resolution;
  value.resolvedAt = new Date().toISOString();
  value.updatedAt = value.resolvedAt;
  return value;
};

import { createHash, randomUUID } from "node:crypto";

export const NUTSTORE_PROTOCOL_VERSION = 1;
export const NUTSTORE_STATE_SCHEMA_VERSION = 1;
export const NUTSTORE_OFFICIAL_ORIGIN = "https://dav.jianguoyun.com";
export const NUTSTORE_DEFAULT_ENDPOINT = `${NUTSTORE_OFFICIAL_ORIGIN}/dav/`;
export const NUTSTORE_DEFAULT_REMOTE_ROOT = "/神思同步/";
export const SYNC_MODES = Object.freeze(["none", "nutstore_direct", "baidu_local_folder"]);
export const CAPABILITY_LEVELS = Object.freeze(["safe_auto", "safe_manual", "unsupported"]);
export const normalizeStorageProtocol = value => {
 const protocol=value||'legacy-v1';
 if(!['legacy-v1','journal-v2'].includes(protocol))throw Object.assign(new Error('不支持的坚果云同步格式'),{code:'NUTSTORE_PROTOCOL_UNSUPPORTED'});
