};
export const OPERATION_STATES = Object.freeze([
  "pending", "scanning", "comparing", "uploading", "downloading", "verifying", "applying",
  "conflict", "retry_wait", "waiting_credentials", "paused", "completed", "cancelled", "failed",
]);

const WINDOWS_RESERVED = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?$/i;
const CONTROL_OR_FORBIDDEN = /[\u0000-\u001f<>:"|?*]/u;

export const normalizeNutstoreEndpoint = (value = NUTSTORE_DEFAULT_ENDPOINT) => {
  let url;
  try { url = new URL(String(value || NUTSTORE_DEFAULT_ENDPOINT).trim()); }
  catch { throw new Error("坚果云 WebDAV URL 无效"); }
  if (url.protocol !== "https:") throw new Error("坚果云直连只允许 HTTPS");
  if (url.origin !== NUTSTORE_OFFICIAL_ORIGIN) throw new Error("当前版本只允许坚果云官方 WebDAV 主机");
  url.username = "";
  url.password = "";
  url.search = "";
  url.hash = "";
  url.pathname = `${url.pathname.replace(/\/{2,}/g, "/").replace(/\/?$/, "/")}`;
  if (!url.pathname.startsWith("/dav/")) throw new Error("坚果云官方 WebDAV URL 必须位于 /dav/");
  return url.toString();
};

const normalizedSegment = (segment) => {
  const value = String(segment || "").normalize("NFC");
  if (!value || value === "." || value === "..") throw new Error("同步逻辑路径包含空段或路径穿越");
  if (CONTROL_OR_FORBIDDEN.test(value) || /[. ]$/u.test(value)) throw new Error("同步逻辑路径包含 Windows 不安全字符");
  if (WINDOWS_RESERVED.test(value)) throw new Error("同步逻辑路径包含 Windows 保留名称");
  return value;
};

export const normalizeLogicalPath = (input) => {
  const raw = String(input || "").trim().replace(/\\/g, "/").normalize("NFC");
  if (!raw) throw new Error("同步逻辑路径不能为空");
  if (/^(?:\/|[a-z]:\/)/i.test(raw)) throw new Error("同步逻辑路径不能是机器绝对路径");
  const segments = raw.split("/").map(normalizedSegment);
  return segments.join("/");
};

export const normalizeRemoteRoot = (input = NUTSTORE_DEFAULT_REMOTE_ROOT) => {
  const raw = String(input || NUTSTORE_DEFAULT_REMOTE_ROOT).trim().replace(/\\/g, "/").normalize("NFC");
  if (/^[a-z]:/i.test(raw) || raw.includes("..")) throw new Error("远程目录不能包含本机路径或路径穿越");
  const segments = raw.split("/").filter(Boolean).map(normalizedSegment);
  if (!segments.length) throw new Error("远程目录不能是 WebDAV 根目录");
  return `/${segments.join("/")}/`;
};

export const logicalPathKey = (value) => normalizeLogicalPath(value).normalize("NFC").toLocaleLowerCase("en-US");
export const sha256 = (value) => createHash("sha256").update(value).digest("hex");
export const stableIdempotencyKey = ({ action, logicalPath, hash = "", deleted = false }) => (
  sha256(`${NUTSTORE_PROTOCOL_VERSION}\n${action}\n${normalizeLogicalPath(logicalPath)}\n${hash}\n${deleted ? 1 : 0}`)
);
export const createTransactionId = (deviceId = "device") => `${String(deviceId).slice(0, 12)}-${Date.now()}-${randomUUID()}`;

export const publicSyncError = (error) => ({
  code: String(error?.code || "NUTSTORE_SYNC_FAILED").replace(/[^A-Z0-9_:-]/gi, "_").slice(0, 80),
  message: String(error?.safeMessage || error?.message || "同步失败")
    .replace(/Basic\s+[A-Za-z0-9+/=]+/gi, "Basic [REDACTED]")
    .replace(/(password|authorization|应用密码)\s*[:=]\s*[^\s,;]+/gi, "$1=[REDACTED]")
    .slice(0, 500),
});

import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import { lstat } from "node:fs/promises";
import { collectAllowedFiles } from "./path-policy.mjs";

export const hashFile = (path) => new Promise((resolveHash, reject) => {
  const hash = createHash("sha256");
  const stream = createReadStream(path,{highWaterMark:1024*1024});
  stream.on("data", (chunk) => hash.update(chunk));
  stream.once("error", reject);
  stream.once("end", () => resolveHash(hash.digest("hex")));
});

const contentTypeFor = (logicalPath) => {
  const lower = logicalPath.toLowerCase();
  if (lower.endsWith(".md")) return "text/markdown; charset=utf-8";
  if (lower.endsWith(".txt")) return "text/plain; charset=utf-8";
  if (lower.endsWith(".json")) return "application/json";
  if (/\.(?:png|jpg|jpeg|webp|gif)$/i.test(lower)) return `image/${lower.split(".").pop().replace("jpg", "jpeg")}`;
  if (/\.(?:mp4|webm|mov)$/i.test(lower)) return "video/mp4";
  if (/\.(?:mp3|wav|m4a)$/i.test(lower)) return "audio/mpeg";
  if (lower.endsWith(".pdf")) return "application/pdf";
  return "application/octet-stream";
};

export const createLocalInventory = async ({ dataRoot, baseline = {}, includeSourcePaths = false, onProgress = null, onScan = null } = {}) => {
  const candidates = await collectAllowedFiles({ dataRoot, onScan });
  const files = [];
  let scanned = 0;
  const unchanged=async item=>{
    let info;
    try {info=await lstat(item.absolutePath);} catch(error) {
      if(!['ENOENT','ENOTDIR'].includes(error?.code))throw error;
    }
    if(!info?.isFile()||info.isSymbolicLink()||['size','mtimeMs','ctimeMs','dev','ino'].some(key=>info[key]!==item[key]))throw Object.assign(new Error('扫描期间本地文件已变化：'+item.logicalPath+'；已停止本轮同步，请重新比较，不会采用混合版本'),{code:'LOCAL_FILE_CHANGED_DURING_SYNC',logicalPath:item.logicalPath});
  };
  const inspect=async item=>{
    await unchanged(item);
    const previous = baseline[item.logicalPath];
    const contentType = contentTypeFor(item.logicalPath);
    const cacheableLargeBinary = !/^(?:text\/|application\/json)/i.test(contentType);
    const hash = cacheableLargeBinary && previous && previous.size === item.size && previous.mtimeMs === item.mtimeMs && previous.ctimeMs === item.ctimeMs && /^[a-f0-9]{64}$/.test(previous.localHash||'')
      ? previous.localHash
      : await hashFile(item.absolutePath);
    await unchanged(item);
    return {
      logicalPath: item.logicalPath,
      hash,
      size: item.size,
      contentType,
      deleted: false,
      ...(includeSourcePaths ? { sourcePath: item.absolutePath, mtimeMs: item.mtimeMs, ctimeMs:item.ctimeMs, birthtimeMs:item.birthtimeMs } : {}),
    };
  };
  // Four bounded readers overlap filesystem latency without buffering media
  // in memory. Await every reader even on failure; no late callbacks or partial
  // inventory may escape into the next sync run.
  for(let offset=0;offset<candidates.length;offset+=4){
    const batch=await Promise.allSettled(candidates.slice(offset,offset+4).map(inspect));
    const failed=batch.find(item=>item.status==='rejected');if(failed)throw failed.reason;
    for(const {value}of batch){files.push(value);scanned+=1;await onProgress?.({scanned,total:candidates.length,logicalPath:value.logicalPath});}
  }
  // A file checked early can change while later media is being hashed. Re-read
  // metadata and membership once at the end, not once per uploaded file.
  const current=await collectAllowedFiles({dataRoot});
  if(current.length!==candidates.length||current.some((item,i)=>item.logicalPath!==candidates[i].logicalPath))throw Object.assign(new Error('扫描期间本地文件清单已变化，已停止本轮同步，请重新比较'),{code:'LOCAL_SCAN_CHANGED'});
  for(let i=0;i<candidates.length;i++)if(['size','mtimeMs','ctimeMs','dev','ino'].some(key=>current[i][key]!==candidates[i][key]))throw Object.assign(new Error('扫描期间本地文件已变化：'+candidates[i].logicalPath+'；已停止本轮同步，请重新比较，不会采用混合版本'),{code:'LOCAL_FILE_CHANGED_DURING_SYNC',logicalPath:candidates[i].logicalPath});
  return { schemaVersion: 1, files, totalFiles: files.length, totalBytes: files.reduce((sum, item) => sum + item.size, 0) };
};

import {randomUUID} from 'node:crypto';
import {normalizeRemoteRoot} from './contracts.mjs';

export const isJournalSafe=capability=>capability?.storageProtocol==='journal-v2'&&capability.journalProbeVersion===1&&['get','put','propfind','mkcol','independentWrites','cleanup'].every(key=>capability[key]===true);

// Append-only storage has no shared overwrite/DELETE commit. Probe the actual
// required operations in a unique disposable directory, not v1's CAS/MOVE.
export async function probeNutstoreJournalCapabilities({client,remoteRoot}){
 const root=normalizeRemoteRoot(remoteRoot).replace(/^\/+|\/+$/g,''),id=randomUUID(),probe=root+'/.shensi-probes/journal-'+id;
 const result={storageProtocol:'journal-v2',journalProbeVersion:1,https:true,get:false,put:false,propfind:false,mkcol:false,independentWrites:false,cleanup:false,capabilityLevel:'unsupported',reasons:[]};
 // Refuse legacy or another journal layout BEFORE creating a probe there.
 for(const old of ['protocol.json','.shensi-sync','.shensi-sync-v2','workspaces','author','.shensi-journal-v1'])if((await client.head(root+'/'+old)).exists)throw Object.assign(Error('此目录仍含旧同步资料，不能原地替换；请选择独立的安全历史目录，原文件和冲突记录会保留'),{code:'NUTSTORE_LEGACY_ROOT'});
 let owned=false;
 try{
  await client.ensureCollections(probe);owned=true;result.mkcol=true;
  const payloads=['A','B'].map(label=>({path:probe+'/'+label+'.txt',bytes:Buffer.from('shensi-journal-probe:'+id+':'+label)}));
  await Promise.all(payloads.map(p=>client.putBuffer(p.path,p.bytes,{contentType:'text/plain'})));result.put=true;
  result.get=(await Promise.all(payloads.map(async p=>(await client.getBuffer(p.path)).buffer.equals(p.bytes)))).every(Boolean);
  const listing=await client.propfind(probe,1),names=new Set(listing.filter(item=>!item.collection).map(item=>decodeURIComponent(item.href).split('/').at(-1)));
  result.propfind=names.has('A.txt')&&names.has('B.txt');result.independentWrites=result.get&&result.propfind;
 }finally{if(owned)await client.remove(probe,{allowMissing:true}).then(()=>{result.cleanup=true;}).catch(()=>{result.reasons.push('测试目录清理未完成，未开放自动同步');});}
 result.capabilityLevel=isJournalSafe(result)?'safe_auto':'unsupported';
 if(result.capabilityLevel==='unsupported')result.reasons.push('安全历史目录的上传、回读或完整列表未通过');
