}

import {logicalPathKey,normalizeLogicalPath,normalizeRemoteRoot} from './contracts.mjs';
import {createHash} from 'node:crypto';
import {extname} from 'node:path';
import {shouldSyncLogicalPath} from './path-policy.mjs';

// Preview only. An initial protocol migration is a union, not a three-way
// deletion replay: local absence cannot delete remote-only data or vice versa.
export function planLegacyNutstoreMigration({local,remote,remoteFiles}){
 const invalid=message=>{throw Object.assign(Error(message),{code:'NUTSTORE_MIGRATION_INCOMPLETE'});};
 const index=(entries,kind)=>{
  if(!Array.isArray(entries))invalid('迁移缺少完整清单');const map=new Map();
  for(const entry of entries){
   const path=normalizeLogicalPath(entry.logicalPath),key=logicalPathKey(path);
   if(path!==entry.logicalPath||!shouldSyncLogicalPath(path)||map.has(key))invalid('迁移路径不在允许范围内或存在名称碰撞');
   if(kind!=='file'&&(!/^[a-f0-9]{64}$/.test(entry.hash)||!Number.isSafeInteger(entry.size)||entry.size<0))invalid('迁移文件摘要或大小缺失');
   map.set(key,entry);
  }return map;
 };
 const a=index(local,'local'),b=index(remote,'remote'),files=index(remoteFiles,'file');
 for(const [key,entry]of b){const file=files.get(key);if(entry.deleted?!!file:!file||file.size!==entry.size)invalid('旧远端登记与实际文件不一致，需先保存并核对双方');}
 for(const key of files.keys())if(!b.has(key))invalid('旧远端存在未登记文件，迁移不得遗漏');
 const items=[];
 for(const key of [...new Set([...a.keys(),...b.keys()])].sort()){
  const local=a.get(key),remote=b.get(key),logicalPath=(local||remote).logicalPath;
  if(local?.deleted)invalid('本地文件清单不能包含推测删除');
  const action=!local?'preserve_remote':!remote?'preserve_local':remote.deleted?'preserve_local_and_tombstone':local.hash===remote.hash?'identical':'preserve_both';
  items.push({logicalPath,action,...local?{local}:{},...remote?{remote}:{}});
 }
 return {kind:'legacy-to-journal-preview',destructive:false,automaticSwitchAllowed:false,items,summary:Object.fromEntries(['identical','preserve_local','preserve_remote','preserve_both','preserve_local_and_tombstone'].map(action=>[action,items.filter(i=>i.action===action).length]))};
}

// Stage only into an independent v2 root. Original data/settings/old remote
// are never written here. The ordinary engine still owns activation/merging.
// Reuse its immutable journal: a lost PUT receipt is reconciled from inventory
// on the next call, never blindly sent again. snapshot owns verified temp bytes.
export async function stageLegacyNutstoreMigration({local,remote,remoteFiles,sourceRoot,repository,snapshot,assertCurrent,checkpoint,maxFiles=25,onProgress,previousPlan}){
 const stop=(message,code='NUTSTORE_MIGRATION_INCOMPLETE')=>{throw Object.assign(Error(message),{code});};
 if(!Number.isInteger(maxFiles)||maxFiles<1||maxFiles>100||typeof snapshot!=='function'||typeof assertCurrent!=='function'||!checkpoint?.load||!checkpoint?.save)stop('迁移缺少快照核验或断点存储');
 const source=normalizeRemoteRoot(sourceRoot),target=normalizeRemoteRoot(repository.paths?.root);
 if(!sourceRoot||!repository.paths?.root||logicalPathKey(source.slice(1,-1))===logicalPathKey(target.slice(1,-1))||source.toLowerCase().startsWith(target.toLowerCase())||repository.paths.metaRoot!==target.slice(1,-1)+'/.shensi-journal-v2')stop('旧目录不可接管；迁移必须使用独立安全历史目录');
 const buildManifest=(local,remote,remoteFiles)=>{
 const plan=planLegacyNutstoreMigration({local,remote,remoteFiles}),entries=[],occupied=new Set(plan.items.map(i=>logicalPathKey(i.logicalPath)));
 const add=(entry,origin,logicalPath=entry.logicalPath)=>entries.push({...entry,logicalPath,origin,originalPath:entry.logicalPath});
 for(const item of plan.items){
  if(item.local)add(item.local,'local');
  if(item.remote&&!item.remote.deleted&&!item.local)add(item.remote,'remote');
  if(item.action==='preserve_both'){
   const extension=extname(item.logicalPath),path=item.logicalPath.slice(0,extension?-extension.length:undefined)+'.conflict-remote-'+item.remote.hash.slice(0,32)+extension,key=logicalPathKey(path);
   if(occupied.has(key)||!shouldSyncLogicalPath(path))stop('迁移冲突副本名称已被占用，双方原文件保留');occupied.add(key);add(item.remote,'remote',path);
  }
 }
 // Source location is not part of a remote manifest or report.
 const digest=createHash('sha256').update(JSON.stringify([source,target,entries.map(({logicalPath,hash,size,origin,originalPath})=>({logicalPath,hash,size,origin,originalPath})),plan.items.filter(i=>i.remote?.deleted).map(i=>i.remote)])).digest('hex');
 return {plan,entries,digest};};
 const {plan,entries,digest}=buildManifest(local,remote,remoteFiles),expected=new Map(entries.map(e=>[e.logicalPath,e]));
 const previous=previousPlan&&buildManifest(previousPlan.local,previousPlan.remote,previousPlan.remoteFiles),oldExpected=new Map((previous?.entries||[]).map(e=>[e.logicalPath,e]));
 // Refresh is additive and explicitly tied to the preceding verified plan.
 // Old published bytes remain immutable revisions; no inferred deletions.
 if(previous){for(const entry of previous.entries)if(!expected.has(entry.logicalPath))stop('刷新迁移清单不能移除原有项，必须保留旧版本','NUTSTORE_MIGRATION_PLAN_CHANGED');if(JSON.stringify(previousPlan.remote)!==JSON.stringify(remote)||JSON.stringify(previousPlan.remoteFiles)!==JSON.stringify(remoteFiles))stop('旧云端变化不能作为本地清单刷新处理','NUTSTORE_MIGRATION_PLAN_CHANGED');}
 let receipt=await checkpoint.load();
 if(receipt&&previous&&receipt.digest===previous.digest&&receipt.source===source&&receipt.target===target){receipt={...receipt,digest,previousDigest:previous.digest,phase:'refreshed',total:entries.length,complete:false};await checkpoint.save(receipt);}
 if(receipt&&(receipt.digest!==digest||receipt.source!==source||receipt.target!==target))stop('原资料或迁移目标已变化；已传版本保留，须重新核对迁移计划','NUTSTORE_MIGRATION_PLAN_CHANGED');
 if(!receipt){receipt={version:1,digest,source,target,phase:'prepared',total:entries.length,tombstones:plan.items.filter(i=>i.remote?.deleted).map(i=>i.remote),uploaded:0,complete:false};await checkpoint.save(receipt);}
 const validate=items=>{
  const map=new Map();for(const item of items){const wanted=expected.get(item.logicalPath),old=oldExpected.get(item.logicalPath),matches=e=>e&&item.hash===e.hash&&item.size===e.size;if(!wanted||item.conflicted||item.deleted||!matches(wanted)&&!matches(old)||map.has(item.logicalPath))stop('迁移目标含不同版本，未覆盖；请核对双方资料','NUTSTORE_MIGRATION_TARGET_CHANGED');map.set(item.logicalPath,item);}return map;
 };
 let uploaded=0;
 try{
  await assertCurrent();
  const present=validate(await repository.inventory());
  const matches=(item,wanted)=>item?.hash===wanted.hash&&item?.size===wanted.size;
  const verifiedCount=items=>[...items.values()].filter(e=>matches(e,expected.get(e.logicalPath))).length;
  await repository.withBatch(async batch=>{
   for(const entry of entries){
    const prior=present.get(entry.logicalPath);if(matches(prior,entry)||uploaded>=maxFiles)continue;
    await snapshot(entry,async sourcePath=>{
     const result=await batch.upload({entry:{...entry,sourcePath},expectedRemoteExists:!!prior,...prior?{expectedRemoteEtag:prior.etag}:{}});
     if(result.hash!==entry.hash||result.size!==entry.size)stop('迁移回读与原快照不符，未切换同步配置');
    });
    uploaded++;receipt={...receipt,phase:'staging',uploaded:verifiedCount(present)+uploaded,complete:false};await checkpoint.save(receipt);await onProgress?.({completed:receipt.uploaded,total:entries.length});
   }
  });
  const current=validate(await repository.inventory());await assertCurrent();
  const verified=verifiedCount(current);receipt={...receipt,phase:verified===entries.length?'staged':'staging',uploaded:verified,complete:verified===entries.length};await checkpoint.save(receipt);
  return {staged:receipt.complete,uploadedThisRun:uploaded,verifiedEntries:verified,total:entries.length,conflictCopies:plan.summary.preserve_both,tombstonesRetained:receipt.tombstones.length,automaticSwitchAllowed:false,personalFullSync:false};
 }catch(error){receipt={...receipt,phase:error.code==='RETRY_WAIT'?'retry_wait':'blocked',complete:false,lastErrorCode:error.code||'NUTSTORE_MIGRATION_FAILED',...(error.retryAfterMs?{retryAt:new Date(Date.now()+error.retryAfterMs).toISOString()}:{})};await checkpoint.save(receipt);throw error;}
}

// Reuse a complete old-protocol inventory only while the provider's delta
// cursor proves its metadata AND payload trees unchanged. Migration writes
// in a sibling directory do not force hundreds of old metadata GETs again.
export function createLegacySnapshotReader({repository,delta,root,scope,checkpoint}){
 const base=root.replace(/^\/+|\/+$/g,''),folder=base.split('/')[0];
 const watched=['.shensi-sync','workspaces','author','protocol.json'].map(p=>base+'/'+p);
 let state,tail=Promise.resolve();
 const fault=(message,code='REMOTE_CHANGED_DURING_SYNC')=>Object.assign(Error(message),{code});
 const fresh=cursor=>({version:1,scope,cursor,complete:false});
 const relevant=path=>watched.some(p=>path===p||path.startsWith(p+'/')||p.startsWith(path+'/'));
 async function refresh(){
  if(!state.cursor){state=fresh((await delta.latest(folder)).cursor);return;}
  const seen=new Set();
  for(let page=0;page<1000;page++){
   if(seen.has(state.cursor))throw fault('旧同步库增量游标循环，未采用缓存','NUTSTORE_DELTA_INVALID');seen.add(state.cursor);
   const change=await delta.changes(folder,state.cursor);
   if(change.reset){state=fresh((await delta.latest(folder)).cursor);return;}
   if(change.entries.some(e=>relevant(e.path.replace(/^\/+|\/+$/g,''))))state=fresh(change.cursor);
   else state.cursor=change.cursor;
   if(!change.hasMore)return;
  }
  throw fault('旧同步库增量页数超过上限，未采用缓存','NUTSTORE_DELTA_INVALID');
 }
 const read=()=>{
  const pending=tail.then(async()=>{
   if(!state){const saved=await checkpoint?.load();state=saved?.version===1&&saved.scope===scope&&typeof saved.cursor==='string'&&saved.cursor.length<=4096&&(!saved.complete||Array.isArray(saved.remote)&&Array.isArray(saved.remoteFiles))?structuredClone(saved):fresh('');}
   try{
    await refresh();
    for(let pass=0;pass<3;pass++){
     if(!state.complete){state.remote=await repository.inventory({readOnly:true});state.remoteFiles=await repository.inventoryFiles();state.complete=true;}
     await refresh();
     if(state.complete){await checkpoint?.save(structuredClone(state));return structuredClone({remote:state.remote,remoteFiles:state.remoteFiles});}
    }
    throw fault('旧同步库扫描期间持续变化，未采用混合清单');
   }catch(error){await checkpoint?.save(structuredClone(state));throw error;}
  });tail=pending.catch(()=>{});return pending;
 };
 return {read};
}

import { randomUUID } from "node:crypto";
import { copyFile, mkdir, open, readFile, rename, rm } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import {setTimeout as delay} from 'node:timers/promises';
import { NUTSTORE_PROTOCOL_VERSION, NUTSTORE_STATE_SCHEMA_VERSION } from "./contracts.mjs";

const cleanDeviceName = (value) => String(value || process.env.COMPUTERNAME || "Windows 电脑").trim().slice(0, 80);
const freshState = (deviceName) => ({
  schemaVersion: NUTSTORE_STATE_SCHEMA_VERSION,
  protocolVersion: NUTSTORE_PROTOCOL_VERSION,
  deviceId: randomUUID(),
  deviceName: cleanDeviceName(deviceName),
  platform: process.platform,
  activeMode: "none",
  enabled: false,
  paused: false,
  capabilityLevel: "unsupported",
  remoteRoot: "/神思同步/",
  lastSuccessfulSyncAt: "",
  lastAttemptAt: "",
  lastErrorCode: "",
  localCursor: 0,
  remoteCursor: "",
  baseline: {},
  outbox: [],
  conflicts: [],
  operations: [],
  retry: {},
  migration: null,
  logs: [],
});

const validState=value=>value&&typeof value==='object'&&!Array.isArray(value)&&/^[0-9a-f-]{36}$/i.test(String(value.deviceId||''));
const damagedState=()=>Object.assign(new Error('坚果云本地同步记录损坏，原记录已保留；未清空同步基线或冲突，请恢复记录后再同步'),{code:'NUTSTORE_STATE_CORRUPT'});
export const writeNutstoreState = async (target, value, {replace=rename,wait=delay}={}) => {
  await mkdir(dirname(target), { recursive: true });
  const temporary = `${target}.${process.pid}.${randomUUID()}.tmp`;
  const previous = `${target}.previous`;
  const handle = await open(temporary, "w", 0o600);
  try {
    await handle.writeFile(`${JSON.stringify(value, null, 2)}\n`, "utf8");
    await handle.sync();
  } finally { await handle.close(); }
  try {
    let existing;
    try { existing=await readFile(target,'utf8'); } catch(error) { if(error.code!=='ENOENT')throw error; }
    if(existing!==undefined){
      let valid=false;try{valid=validState(JSON.parse(existing));}catch{}
      // Recovery must not overwrite the last good backup with corrupt bytes.
      if(valid){
        const priorTemporary=previous+'.'+randomUUID()+'.tmp';
        try {await copyFile(target,priorTemporary);await replace(priorTemporary,previous);}finally{await rm(priorTemporary,{force:true}).catch(()=>{});}
      }else await copyFile(target,target+'.damaged-'+randomUUID());
    }
    for(let attempt=0;;attempt++){
      try{await replace(temporary,target);break;}
      catch(error){if(!['EPERM','EACCES','EBUSY'].includes(error.code)||attempt>=4)throw error;await wait(50*(attempt+1));}
    }
  } finally {await rm(temporary,{force:true}).catch(()=>{});}
};

const sanitizeState = (value, deviceName) => {
  const base = freshState(deviceName);
  const input = value && typeof value === "object" ? value : {};
  const merged = { ...base, ...input };
  merged.schemaVersion = NUTSTORE_STATE_SCHEMA_VERSION;
  merged.protocolVersion = NUTSTORE_PROTOCOL_VERSION;
  merged.deviceId = /^[0-9a-f-]{36}$/i.test(String(input.deviceId || "")) ? input.deviceId : base.deviceId;
  merged.deviceName = cleanDeviceName(input.deviceName || deviceName);
  merged.platform = String(input.platform || process.platform);
  for (const key of ["baseline", "retry"]) if (!merged[key] || typeof merged[key] !== "object" || Array.isArray(merged[key])) merged[key] = {};
  for (const key of ["outbox", "conflicts", "operations", "logs"]) if (!Array.isArray(merged[key])) merged[key] = [];
  for (const secretKey of ["password", "authorization", "credentials", "apiKey", "token"]) delete merged[secretKey];
  merged.logs = merged.logs.slice(-500);
  merged.operations = merged.operations.slice(-2000);
  if (!merged.enabled || merged.activeMode !== "nutstore_direct") {
    merged.outbox = merged.outbox.filter((item) => ["completed", "cancelled"].includes(item?.status)).slice(-200);
  } else {
    let fullScanKept = false;
    merged.outbox = merged.outbox.filter((item) => {
      const pendingFullScan = item?.logicalPath === "*" && item?.action === "scan" && !["completed", "cancelled"].includes(item?.status);
      if (!pendingFullScan) return true;
      if (fullScanKept) return false;
      fullScanKept = true;
      return true;
    }).slice(-2000);
  }
  return merged;
};

export const createNutstoreLocalState = ({ machineRoot, deviceName = "" } = {}) => {
  if (!machineRoot) throw new Error("machineRoot is required");
  const stateRoot = resolve(machineRoot, "machine-sessions", "nutstore-sync-v1");
  const statePath = join(stateRoot, "state.json");
  let queue = Promise.resolve();
  let committed = null;
  const readState = async () => {
    const readValid=async path=>{const value=JSON.parse(await readFile(path,'utf8'));if(!validState(value))throw damagedState();return sanitizeState(value,deviceName);};
    try { return await readValid(statePath); }
    catch (error) {
      if (error?.code !== "ENOENT" && !(error instanceof SyntaxError)&&error.code!=='NUTSTORE_STATE_CORRUPT') throw error;
      try { return await readValid(`${statePath}.previous`); }
      catch(previousError){
        if(previousError.code!=='ENOENT'&&!(previousError instanceof SyntaxError)&&previousError.code!=='NUTSTORE_STATE_CORRUPT')throw previousError;
        if(error.code!=='ENOENT'||previousError.code!=='ENOENT')throw damagedState();
      }
      const state = freshState(deviceName);
      await writeNutstoreState(statePath, state);
      return state;
    }
  };
  const load = async () => {
    await queue;
    const state = await readState();
    committed = structuredClone(state);
    return state;
  };
  const update = (mutator) => {
    const task = queue.then(async () => {
      const state = await readState();
      committed = structuredClone(state);
      const returned = await mutator(state);
      const next = sanitizeState(returned || state, deviceName);
      await writeNutstoreState(statePath, next);
      committed = structuredClone(next);
      return next;
    });
    queue = task.catch(() => {});
    return task;
  };
  // UI inspection reads only the last committed state, never a live mutator.
  // Transactional decisions still use load() and retain their queue barrier.
  const snapshot = async () => structuredClone(committed || await load());
  return { load, snapshot, update, paths: { stateRoot, statePath, previousPath: `${statePath}.previous` } };
};

import { randomUUID } from "node:crypto";
import { normalizeLogicalPath, stableIdempotencyKey } from "./contracts.mjs";

export const enqueueOutboxOperation = (state, input = {}) => {
  const logicalPath = input.logicalPath === "*" ? "*" : normalizeLogicalPath(input.logicalPath);
  const action = String(input.action || "scan");
  // A full inventory scan supersedes every older pending full scan. Local
  // saves can arrive much faster than a WebDAV run; keeping one row per save
  // made an offline/disabled account grow an unbounded multi-megabyte queue.
  if (logicalPath === "*" && action === "scan") {
    const pendingScan = state.outbox.find((item) => item.logicalPath === "*" && item.action === "scan" && !["completed", "cancelled"].includes(item.status));
    if (pendingScan) {
      pendingScan.updatedAt = new Date().toISOString();
      return pendingScan;
    }
  }
  const idempotencyKey = input.idempotencyKey || (logicalPath === "*" ? `scan:${state.localCursor || 0}` : stableIdempotencyKey({ action, logicalPath, hash: input.hash || "", deleted: input.deleted === true }));
  const existing = state.outbox.find((item) => item.idempotencyKey === idempotencyKey && !["completed", "cancelled"].includes(item.status));
  if (existing) return existing;
  if (logicalPath !== "*" && !["delete"].includes(action)) {
    state.outbox = state.outbox.filter((item) => item.logicalPath !== logicalPath || ["completed", "cancelled"].includes(item.status) || item.action === "delete");
  }
  const operation = { id: input.id || randomUUID(), idempotencyKey, logicalPath, action, hash: String(input.hash || ""), deleted: input.deleted === true, status: "pending", attempt: 0, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), retryAt: "", errorCode: "" };
  state.outbox.push(operation);
  return operation;
};

export const updateOutboxOperation = (state, id, patch = {}) => {
  const operation = state.outbox.find((item) => item.id === id);
  if (!operation) return null;
  Object.assign(operation, patch, { updatedAt: new Date().toISOString() });
  return operation;
};

import { lstat, readdir, readFile } from "node:fs/promises";
import { relative, resolve, sep } from "node:path";
import { logicalPathKey, normalizeLogicalPath } from "./contracts.mjs";

const DEFAULT_ALLOWED_ROOTS = Object.freeze(new Set([
  "作品", "笔记", "回收站", "Skill库", "创作经验", "经验仓", "experience-store", "能力模板", "plugins", "core-drafts", "member-models",
]));
const NEVER_SYNC_ROOTS = Object.freeze(new Set([
  "DesktopRuntime", "machine-sessions", "updates", "update-coordination", "diagnostics", "runtime",
  "provider-state", "generation-jobs", "generation-attempts", "recovery", "连接", "迁移", "迁移备份",
  "config", "cache", "caches", "logs", "crashpad", "browser-profile",
]));
const TEMP_OR_SECRET = /(?:^|\/)(?:\.git|node_modules|credentials?|secrets?|tokens?|cookies?|crashdumps?)(?:\/|$)|(?:\.tmp|\.lock|\.pending|\.part|\.download|\.dmp|\.log)$/i;

export const isAllowedSyncRoot = (name) => DEFAULT_ALLOWED_ROOTS.has(String(name || "").normalize("NFC"));

const AUTHOR_LEVEL_ROOTS = Object.freeze(new Set(["Skill库", "创作经验", "经验仓", "experience-store", "能力模板"]));
export const isAuthorLevelLogicalPath = (logicalPath) => AUTHOR_LEVEL_ROOTS.has(normalizeLogicalPath(logicalPath).split("/")[0]);

export const shouldSyncLogicalPath = (logicalPath) => {
  const normalized = normalizeLogicalPath(logicalPath);
  const [root] = normalized.split("/");
  if (!isAllowedSyncRoot(root) || NEVER_SYNC_ROOTS.has(root)) return false;
  if(root==='member-models')return normalized===root||/^member-models\/[a-f0-9]{64}\.sealed(?:\.conflict-remote-(?:[a-f0-9]{8}|[a-f0-9]{32}))?\.json$/.test(normalized);
  if(root==='plugins'&&!/^(?:plugins\/(?:official\.document-chat|official\.whiteboard-generation|official\.works|whiteboard-consoles-v2))(?:\/|$)/.test(normalized))return false;
  if(root==='plugins'&&/\.(?:[cm]?js|html|css|exe|dll|node|zip)$/i.test(normalized))return false;
  if(normalized.startsWith('plugins/official.works/')){
    const parts=normalized.split('/');
    if(parts.length>4||parts.length===4&&!/^(?:tool-jobs|tool-workspace|book-references)(?:\.conflict-remote-(?:[a-f0-9]{8}|[a-f0-9]{32}))?\.json$/.test(parts[3]))return false;
  }
  if (root === "experience-store" && /(?:\.backup\.json$|\/migration-snapshots\/)/i.test(normalized)) return false;
  return !TEMP_OR_SECRET.test(normalized);
};

export const assertPathInsideRoot = ({ dataRoot, absolutePath }) => {
  const root = resolve(dataRoot);
  const target = resolve(absolutePath);
  const rel = relative(root, target);
  if (!rel || rel.startsWith(`..${sep}`) || rel === ".." || rel.startsWith("/") || rel.startsWith("\\")) {
    throw new Error("同步文件必须位于神思数据目录内");
  }
  return rel;
};

export const collectAllowedFiles = async ({ dataRoot, onScan = null }) => {
  const root = resolve(dataRoot);
  const results = [];
  const collisions = new Map();
  const scanChanged = error => {
    if (['ENOENT','ENOTDIR'].includes(error?.code)) throw Object.assign(new Error('扫描期间资料目录已变化，已停止同步；不会把未读到的文件当成删除'), {code:'LOCAL_SCAN_CHANGED',cause:error});
    throw error;
  };
  const walk = async (absoluteDirectory, logicalDirectory) => {
    const entries = await readdir(absoluteDirectory, { withFileTypes: true }).catch(scanChanged);
    entries.sort((a, b) => a.name.localeCompare(b.name, "zh-CN"));
    // Bounded metadata prefetch avoids a serial filesystem round trip per
    // file on large libraries. Process in the original order; no symlink or
    // membership-envelope validation is skipped and no file is changed.
    const allowed = entries.filter(entry => shouldSyncLogicalPath(normalizeLogicalPath(`${logicalDirectory}/${entry.name}`)));
    for (let offset=0; offset<allowed.length; offset+=8) {
    const batch=allowed.slice(offset,offset+8),infos=await Promise.all(batch.map(entry=>lstat(resolve(absoluteDirectory,entry.name)).catch(scanChanged)));
    for (const [index,entry] of batch.entries()) {
      const logicalPath = normalizeLogicalPath(`${logicalDirectory}/${entry.name}`);
      if (!shouldSyncLogicalPath(logicalPath)) continue;
      const absolutePath = resolve(absoluteDirectory, entry.name);
      assertPathInsideRoot({ dataRoot: root, absolutePath });
      const info = infos[index];
      if (info.isSymbolicLink()) continue;
      const key = logicalPathKey(logicalPath);
      if (collisions.has(key) && collisions.get(key) !== logicalPath) {
        const error = new Error(`同步路径存在大小写或 Unicode 规范化碰撞：${collisions.get(key)} / ${logicalPath}`);
        error.code = "SYNC_PATH_COLLISION";
        throw error;
      }
      collisions.set(key, logicalPath);
      if (info.isDirectory()) await walk(absolutePath, logicalPath);
      else if (info.isFile()) {
        if(logicalPath.startsWith('member-models/')){
          let sealed;try{if(info.size>1024*1024)throw new Error();sealed=JSON.parse(await readFile(absolutePath,'utf8'));if(sealed.format!=='shensi-member-sync-v1'||Object.keys(sealed).sort().join(',')!=='ciphertext,format,issuer,iv,memberId,salt,tag'||typeof sealed.issuer!=='string'||typeof sealed.memberId!=='string'||['ciphertext','salt','iv','tag'].some(k=>typeof sealed[k]!=='string')||! /^[A-Za-z0-9_-]+$/.test(sealed.ciphertext)||! /^[A-Za-z0-9_-]{22}$/.test(sealed.salt)||! /^[A-Za-z0-9_-]{16}$/.test(sealed.iv)||! /^[A-Za-z0-9_-]{22}$/.test(sealed.tag))throw new Error();}catch{throw Object.assign(new Error('会员同步文件未通过密封格式检查，已阻止上传'),{code:'MEMBER_SEAL_INVALID'});}
        }
        results.push({ logicalPath, absolutePath, size: info.size, mtimeMs: info.mtimeMs, ctimeMs: info.ctimeMs, birthtimeMs:info.birthtimeMs, dev:info.dev, ino:info.ino });await onScan?.({discovered:results.length,logicalPath});
      }
    }
    }
  };
  let roots;
  try {
    const info=await lstat(root);
    if(!info.isDirectory()||info.isSymbolicLink())throw new Error('资料根不是可读取的实际目录');
    roots=await readdir(root,{withFileTypes:true});
  } catch(error) {
    throw Object.assign(new Error('本地资料目录不可用，已停止同步；不会按空资料库处理'),{code:'LOCAL_DATA_ROOT_UNAVAILABLE',cause:error});
  }
  for (const entry of roots) {
    if (!entry.isDirectory() || entry.isSymbolicLink() || !isAllowedSyncRoot(entry.name)) continue;
    await walk(resolve(root, entry.name), normalizeLogicalPath(entry.name));
  }
  return results;
};

export const syncPathPolicy = Object.freeze({ allowedRoots: [...DEFAULT_ALLOWED_ROOTS], authorLevelRoots: [...AUTHOR_LEVEL_ROOTS], excludedRoots: [...NEVER_SYNC_ROOTS] });

import { createHash, randomUUID } from "node:crypto";
import { dirname } from "node:path";
import { NUTSTORE_PROTOCOL_VERSION, createTransactionId, logicalPathKey, normalizeLogicalPath, normalizeRemoteRoot } from "./contracts.mjs";
import { acknowledgeTombstone, createTombstone } from "./tombstones.mjs";
import { isAuthorLevelLogicalPath, shouldSyncLogicalPath } from "./path-policy.mjs";

const trim = (value) => String(value || "").replace(/^\/+|\/+$/g, "");
const json = (value) => Buffer.from(`${JSON.stringify(value, null, 2)}\n`, "utf8");
const entryName = (logicalPath) => `${createHash("sha256").update(normalizeLogicalPath(logicalPath), "utf8").digest("hex")}.json`;
const isConditionalRejection = (error) => ["WEBDAV_HTTP_409", "WEBDAV_HTTP_412"].includes(error?.code);
const remoteChanged = (message) => Object.assign(new Error(message), { code: "REMOTE_CHANGED_DURING_SYNC" });

export const createNutstoreRemoteRepository = ({ client, remoteRoot, deviceId, capability = null }) => {
  const root = trim(normalizeRemoteRoot(remoteRoot));
  const hasCapabilityProbe = capability && typeof capability === "object";
  const manualMode = capability?.capabilityLevel === "safe_manual";
  const supportsIfNoneMatch = !hasCapabilityProbe || capability.ifNoneMatch === true;
  const supportsIfMatch = !hasCapabilityProbe || capability.ifMatch === true;
  const supportsConditionalMove = !hasCapabilityProbe || capability.conditionalMove === true;
  const supportsConditionalDelete = capability?.conditionalDelete === true;
  const at = (suffix = "") => `${root}${suffix ? `/${trim(suffix)}` : ""}`;
  const metaRoot = at(".shensi-sync");
  const entryRoot = `${metaRoot}/entries`;
  const tombstoneRoot = `${metaRoot}/tombstones`;
  const stagingRoot = `${metaRoot}/staging`;
  const deviceRoot = `${metaRoot}/devices`;
  const dataPath = (logicalPath) => {
    const normalized = normalizeLogicalPath(logicalPath);
    return at(`${isAuthorLevelLogicalPath(normalized) ? "author" : "workspaces"}/${normalized}`);
  };
  const metadataPath = (logicalPath) => `${entryRoot}/${entryName(logicalPath)}`;
  const tombstonePath = (logicalPath) => `${tombstoneRoot}/${entryName(logicalPath)}`;
  let initializationPromise = null;

  const putBufferIfAbsent = async (remotePath, buffer, options = {}) => {
    const existing = await client.head(remotePath);
    if (existing.exists) return { created: false, etag: existing.etag || "" };
    if (supportsIfNoneMatch) {
      try {
        return { created: true, ...(await client.putBuffer(remotePath, buffer, { ...options, ifNoneMatch: true })) };
      } catch (error) {
        if (!manualMode || !isConditionalRejection(error)) throw error;
      }
      const rechecked = await client.head(remotePath);
      if (rechecked.exists) throw remoteChanged("远程文件在兼容写入前已出现，已停止覆盖");
    }
    return { created: true, ...(await client.putBuffer(remotePath, buffer, options)) };
  };

  const putUniqueStagingFile = async (remotePath, sourcePath, options = {}) => {
    const existing = await client.head(remotePath);
    if (existing.exists) throw remoteChanged("随机上传暂存文件意外存在，已停止写入");
    if (supportsIfNoneMatch) {
      try { return await client.putFile(remotePath, sourcePath, { ...options, ifNoneMatch: true }); }
      catch (error) {
        if (!manualMode || !isConditionalRejection(error)) throw error;
      }
      const rechecked = await client.head(remotePath);
      if (rechecked.exists) throw remoteChanged("远程暂存文件在兼容写入前已出现，已停止覆盖");
    }
    return client.putFile(remotePath, sourcePath, options);
  };

  const assertRemoteSnapshot = ({ current, expectedRemoteEtag = "", expectedRemoteExists = null, manualOverwriteConfirmed = false }) => {
    if (expectedRemoteExists === false && current.exists) throw remoteChanged("远程目标在扫描后已被创建，需要重新比较");
    if (expectedRemoteExists === true && !current.exists) throw remoteChanged("远程目标在扫描后已被删除，需要重新比较");
    if (expectedRemoteEtag && current.exists && current.etag !== expectedRemoteEtag) throw remoteChanged("远程 ETag 在提交前已变化，需要重新比较");
    if (manualMode && expectedRemoteExists === true && !expectedRemoteEtag && !manualOverwriteConfirmed) throw remoteChanged("远程目标缺少稳定 ETag，不能安全覆盖，请在冲突中心确认");
  };

  const initialize = ({ deviceName = "Windows 电脑", platform = "windows" } = {}) => {
    if (!initializationPromise) {
      initializationPromise = (async () => {
        await client.ensureCollections(root);
        for (const directory of [metaRoot, entryRoot, tombstoneRoot, stagingRoot, deviceRoot, at("workspaces"), at("author")]) await client.ensureCollections(directory);
        const protocol = { schemaVersion: 1, protocolVersion: NUTSTORE_PROTOCOL_VERSION, kind: "shensi-nutstore-webdav", collaboration: "eventual-consistency", pathEncoding: "utf-8-nfc", createdAt: new Date().toISOString() };
        await putBufferIfAbsent(at("protocol.json"), json(protocol), { contentType: "application/json" });
        await client.putBuffer(`${deviceRoot}/${deviceId}.json`, json({ schemaVersion: 1, protocolVersion: NUTSTORE_PROTOCOL_VERSION, deviceId, deviceName, platform, lastSeenAt: new Date().toISOString() }), { contentType: "application/json" });
      })().catch((error) => {
        initializationPromise = null;
        throw error;
      });
    }
    return initializationPromise;
  };

  const listMetadataDirectory = async (directory) => {
    const listing = await client.propfind(directory, 1);
    const values = [];
    for (const item of listing) {
      if (item.collection || !/\.json(?:$|[?#])/i.test(item.href)) continue;
      const name = decodeURIComponent(String(item.href).split("/").filter(Boolean).pop() || "");
      if (!/^[a-f0-9]{64}\.json$/i.test(name)) continue;
      try {
        const read = await client.getBuffer(`${directory}/${name}`);
        values.push(JSON.parse(read.buffer.toString("utf8")));
      } catch (error) {
        if (error instanceof SyntaxError) {
          error.code = "REMOTE_METADATA_CORRUPT";
          throw error;
        }
        throw error;
      }
    }
    return values;
  };

  const inventory = async ({ readOnly = false } = {}) => {
    // A migration preview must not create protocol/device metadata in the
    // original root. Missing/corrupt directories still fail, never mean empty.
    if (!readOnly) await initialize();
    const [entries, tombstones] = await Promise.all([listMetadataDirectory(entryRoot), listMetadataDirectory(tombstoneRoot)]);
    const byPath = new Map();
    for (const entry of entries) {
      const logicalPath = normalizeLogicalPath(entry.logicalPath);
      byPath.set(logicalPath, { logicalPath, hash: String(entry.hash || ""), size: Number(entry.size || 0), contentType: String(entry.contentType || "application/octet-stream"), etag: String(entry.etag || ""), deleted: false, updatedAt: entry.updatedAt || "",modifiedAt:entry.modifiedAt||'',createdAt:entry.createdAt||'' });
    }
    for (const tombstone of tombstones) {
      const logicalPath = normalizeLogicalPath(tombstone.logicalPath);
      const existing = byPath.get(logicalPath);
      if (!existing || Date.parse(tombstone.deletedAt || 0) >= Date.parse(existing.updatedAt || 0)) byPath.set(logicalPath, { logicalPath, hash: String(tombstone.lastKnownRemoteHash || tombstone.baseHash || ""), size: 0, contentType: "application/x-shensi-tombstone", etag: "", deleted: true, tombstone });
    }
    return [...byPath.values()].sort((a, b) => a.logicalPath.localeCompare(b.logicalPath, "zh-CN"));
  };

  // Metadata alone misses files uploaded before a crashed metadata commit.
  // Migration must enumerate the original payload trees too, without creating
  // directories or treating a missing/truncated listing as an empty library.
  const inventoryFiles = async () => {
    const files = [], endpoint = client.endpoint || "https://dav.jianguoyun.com/dav/";
    const bad = () => Object.assign(new Error("旧同步目录清单含非预期路径，迁移预览已停止"), { code: "WEBDAV_INVALID_LISTING" });
    const walk = async (directory, logicalDirectory = "", depth = 0) => {
      if (depth > 100 || files.length > 100000) throw bad();
      const base = new URL(client.urlFor?.(directory) || directory.split("/").map(encodeURIComponent).join("/"), endpoint);
      const prefix = decodeURIComponent(base.pathname).replace(/\/$/, ""), seen = new Set();
      for (const item of await client.propfind(directory, 1)) {
        const url = new URL(item.href, endpoint), decoded = decodeURIComponent(url.pathname).replace(/\/$/, "");
        if (url.origin !== base.origin || url.search || url.hash) throw bad();
        if (decoded === prefix && item.collection) continue;
        const name = decoded.slice(prefix.length + 1);
        if (!decoded.startsWith(prefix + "/") || !name || name.includes("/") || name.includes("\\") || [".", ".."].includes(name) || seen.has(name) || item.status && !/^HTTP\/\S+ 200\b/.test(item.status)) throw bad();
        seen.add(name);
        const logicalPath = normalizeLogicalPath(logicalDirectory ? logicalDirectory + "/" + name : name);
        if (item.collection) await walk(directory + "/" + name, logicalPath, depth + 1);
        else files.push({ logicalPath, remotePath: directory + "/" + name, size: item.size, etag: item.etag || "", syncAllowed: shouldSyncLogicalPath(logicalPath) });
      }
    };
    await walk(at("workspaces")); await walk(at("author"));
    const paths = new Set();
    for (const file of files) { const key=logicalPathKey(file.logicalPath); if (paths.has(key)) throw bad(); paths.add(key); }
    return files.sort((a, b) => a.logicalPath.localeCompare(b.logicalPath, "zh-CN"));
  };

  const upload = async ({ entry, expectedRemoteEtag = "", expectedRemoteExists = null, manualOverwriteConfirmed = false, onProgress }) => {
    const logicalPath = normalizeLogicalPath(entry.logicalPath);
    const transactionId = createTransactionId(deviceId);
    const staging = `${stagingRoot}/${transactionId}.upload`;
    const target = dataPath(logicalPath);
    await client.ensureCollections(dirname(target).replace(/\\/g, "/"));
    const current = await client.head(target);
    assertRemoteSnapshot({ current, expectedRemoteEtag, expectedRemoteExists, manualOverwriteConfirmed });
    await putUniqueStagingFile(staging, entry.sourcePath, { contentType: entry.contentType, onProgress });
    const rechecked = await client.head(target);
    assertRemoteSnapshot({ current: rechecked, expectedRemoteEtag, expectedRemoteExists, manualOverwriteConfirmed });
    try {
      if (!rechecked.exists) await client.move(staging, target, { overwrite: false });
      else {
        if (supportsConditionalMove && rechecked.etag) {
          await client.move(staging, target, { overwrite: true, destinationEtag: rechecked.etag });
        } else if (supportsIfMatch && rechecked.etag) {
          // Nutstore rejects MOVE overwrite on some accounts, but supports a
          // conditional PUT. Re-upload the already verified local source with
          // If-Match so ordinary manual sync remains race-safe.
          await client.putFile(target, entry.sourcePath, {
            contentType: entry.contentType,
            ifMatch: rechecked.etag,
            onProgress,
          });
          await client.remove(staging, { allowMissing: true }).catch(() => {});
        } else {
          if (!manualMode || !manualOverwriteConfirmed) throw remoteChanged("服务端不支持安全条件替换，不能覆盖已有远程文件，请在冲突中心确认");
          // An explicitly confirmed replacement still avoids MOVE overwrite:
          // rotate the old target to a unique backup, move the completed
          // staging upload into the now-empty path, and restore on failure.
          const backup = `${stagingRoot}/${transactionId}.previous`;
          await client.move(target, backup, {
            overwrite: false,
            // This explicit conflict choice authorizes the backup-and-swap.
            // Do not resend If-Match when the server already rejected it.
            ifMatch: supportsIfMatch ? rechecked.etag || "" : "",
          });
          try {
            await client.move(staging, target, { overwrite: false });
          } catch (error) {
            await client.move(backup, target, { overwrite: false }).catch(() => {});
            throw error;
          }
          await client.remove(backup, { allowMissing: true }).catch(() => {});
        }
      }
    } catch (error) {
      await client.remove(staging, { allowMissing: true }).catch(() => {});
      if (isConditionalRejection(error)) throw remoteChanged("远程目标在移动提交前已变化，需要重新比较");
      throw error;
    }
    const verified = await client.head(target);
    if (!verified.exists || verified.size !== entry.size) throw Object.assign(new Error("远程上传校验失败"), { code: "REMOTE_VERIFY_FAILED" });
    const metadata = { schemaVersion: 1, protocolVersion: NUTSTORE_PROTOCOL_VERSION, logicalPath, hash: entry.hash, size: entry.size, contentType: entry.contentType, etag: verified.etag, transactionId, updatedByDeviceId: deviceId, updatedAt: new Date().toISOString(),modifiedAt:entry.modifiedAt||(entry.mtimeMs?new Date(entry.mtimeMs).toISOString():''),createdAt:entry.createdAt||(entry.birthtimeMs?new Date(entry.birthtimeMs).toISOString():'') };
    await client.putBuffer(metadataPath(logicalPath), json(metadata), { contentType: "application/json" });
    await client.remove(tombstonePath(logicalPath), { allowMissing: true });
    return metadata;
  };

  const download = async ({ entry, temporaryPath, onProgress }) => client.downloadToFile(dataPath(entry.logicalPath), temporaryPath, { expectedSize: entry.size, onProgress });

  const remove = async ({ entry, baseHash = "", expectedRemoteEtag = "", expectedRemoteExists = null, manualOverwriteConfirmed = false }) => {
    const logicalPath = normalizeLogicalPath(entry.logicalPath);
    const transactionId = createTransactionId(deviceId);
    const current = await client.head(dataPath(logicalPath));
    assertRemoteSnapshot({ current, expectedRemoteEtag, expectedRemoteExists, manualOverwriteConfirmed });
    if (current.exists && (!supportsConditionalDelete || !current.etag) && (!manualMode || !manualOverwriteConfirmed)) throw remoteChanged("服务端不支持安全条件删除，不能直接删除远程文件，请在冲突中心确认");
    const tombstone = createTombstone({ logicalPath, deviceId, baseHash, lastKnownRemoteHash: entry.hash || baseHash, transactionId });
    await client.putBuffer(tombstonePath(logicalPath), json(tombstone), { contentType: "application/json" });
    try { await client.remove(dataPath(logicalPath), { ifMatch: supportsConditionalDelete ? current.etag : "", allowMissing: true }); }
    catch (error) {
      if (isConditionalRejection(error)) {
        await client.remove(tombstonePath(logicalPath), { allowMissing: true }).catch(() => {});
        throw remoteChanged("远程目标在删除提交前已变化，需要重新比较");
      }
      throw error;
    }
    await client.remove(metadataPath(logicalPath), { allowMissing: true });
    return tombstone;
  };

  const acknowledgeDeletion = async ({ entry } = {}) => {
    const logicalPath = normalizeLogicalPath(entry?.logicalPath);
    const path = tombstonePath(logicalPath);
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const current = await client.getBuffer(path);
      const tombstone = JSON.parse(current.buffer.toString("utf8"));
      const acknowledged = acknowledgeTombstone(tombstone, deviceId);
      if ((tombstone.acknowledgedDevices || []).includes(deviceId)) return acknowledged;
      if (manualMode && !supportsIfMatch) return tombstone;
      try {
        await client.putBuffer(path, json(acknowledged), { contentType: "application/json", ifMatch: current.etag });
        return acknowledged;
      } catch (error) {
        if (error?.code !== "WEBDAV_HTTP_412" || attempt === 2) throw error;
      }
    }
    throw Object.assign(new Error("删除墓碑确认写入失败"), { code: "TOMBSTONE_ACK_FAILED" });
  };

  return { initialize, inventory, inventoryFiles, upload, download, remove, acknowledgeDeletion, paths: { root, metaRoot, entryRoot, tombstoneRoot, stagingRoot, deviceRoot }, dataPath };
};

import {randomUUID} from 'node:crypto';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {rm} from 'node:fs/promises';
import {hashFile} from './inventory.mjs';
import {createSyncRevisionJournal} from '../../../../core/src/sync-revision-journal.mjs';
