export function createNutstoreRevisionJournal({client,remoteRoot,deviceId,layoutVersion=1,checkpoint,scope}){
 const io={
  ensure:path=>client.ensureCollections(path),head:path=>client.head(path),
  list:async(path,kind='files')=>{
