   dialog.querySelector('[data-progress-summary]').textContent=`${phase} · ${status.progress?.completed||0} / ${status.progress?.total||0} 项${status.lastErrorCode?' · '+(status.lastErrorMessage||status.lastErrorCode):''}${status.retryAt?' · 可重试时间：'+new Date(status.retryAt).toLocaleString():''}`;
   const container=dialog.querySelector('[data-progress-files]'),scroll=container.scrollTop;
   container.innerHTML=operations.length?[...operations].reverse().map(item=>`<section class="nutstore-progress-file"><strong>${h(item.logicalPath)}</strong><div><span>${h(actions[item.action]||item.action)} · ${h(states[item.status]||item.status)}${item.transferPhase==='verifying'&&!['completed','failed','conflict'].includes(item.status)?'（等待校验）':''}</span><span>${Math.min(100,Math.max(0,Number(item.progress)||0))}%</span></div><progress max="100" value="${Math.min(100,Math.max(0,Number(item.progress)||0))}" aria-label="文件进度"></progress><small>${bytes(item.transferred)} / ${bytes(item.size)}${item.errorCode?' · '+h(item.errorCode):''}</small></section>`).join(''):'<p>暂无文件传输记录。</p>';
   container.scrollTop=scroll;
  }catch(error){if(!disposed)dialog.querySelector('[data-progress-summary]').textContent='暂时无法读取进度：'+error.message;}
  if(!disposed)timer=setTimeout(refresh,800);
 }
 void refresh();return dialog;
}

