import {escapeHtml as h} from './editor.js';
import {syncCapabilityDetails} from './nutstore-capabilities.js';
import {openNutstoreProgress} from './nutstore-progress.js';
import {openNutstoreNotebooks} from './nutstore-notebooks.js';
import {openNutstoreConflicts} from './nutstore-feedback.js';

function capabilityHtml(capability){
 const details=syncCapabilityDetails(capability);
 if(capability?.storageProtocol==='journal-v2')return `<details data-sync-capabilities><summary>安全历史同步检测结果</summary>${details.checks.map(c=>`<p>${c.passed?'✓':'—'} ${h(c.label)}：${c.passed?'通过':'未通过或未验证'}</p>`).join('')}${details.reasons.map(reason=>`<p>${h(reason)}</p>`).join('')}<p>每次修改新增独立版本，不覆盖共同文件头；并发修改保留为冲突分支。先完成首次预览，再确认启用自动同步。旧同步目录不会原地替换，历史不会自动清理。</p></details>`;
 return `<details data-sync-capabilities><summary>自动同步条件与检测结果</summary>${details.checks.map(c=>`<p>${c.passed?'✓':'—'} ${h(c.label)}：${c.passed?'通过':'未通过或未验证'}</p>`).join('')}${details.reasons.map(reason=>`<p>${h(reason)}</p>`).join('')}<p>解除条件：连接通过上述正反条件检测，完成首次同步预览并确认启用，再勾选自动同步。未通过不能靠重复登录、付费升级或强行勾选解决；需上游支持相应语义，或另行升级同步协议并完成并发冲突验收。</p><p>未满足时仍可手动预览并确认同步；网络异常不会阻止本地保存。</p></details>`;
}

export async function mountNutstoreSettings(root,{api,notebookApi,modal,toast,changed,canResolve}){
 let currentStatus,busy=false,previewToken='',viewRevision=0;
 const q=s=>root.querySelector(s);
 async function render(){
  const revision=++viewRevision,status=await api('status');
  if(!root.isConnected||revision!==viewRevision)return;
  currentStatus=status;previewToken='';const loggedIn=!!status.account&&status.credentialAvailable,automatic=status.capabilityLevel==='safe_auto';
  root.innerHTML=`<section class="nutstore-settings"><header class="nutstore-heading"><div><h3>坚果云同步</h3><p>通过 WebDAV 在多台电脑间同步笔记与附件</p></div><span class="badge" data-sync-login-status>${loggedIn?'已登录':'未登录'}</span></header>${loggedIn?`
   <section class="nutstore-identity" data-sync-connected><strong>${h(status.account)}</strong><p>${h(status.deviceName)} · ${h(status.remoteRoot)}</p><div class="setting-inline"><button type="button" data-sync="test">连通性测试</button><button type="button" data-sync="disconnect">退出登录</button><button type="button" data-sync="switch">更换账号</button></div></section>
   <section><div class="nutstore-summary"><strong>${!status.enabled?'待启用同步':status.paused?'已暂停':status.phase==='retry_wait'?'等待服务恢复':'已连接'}</strong><span>待上传 ${status.pendingUpload} · 待下载 ${status.pendingDownload} · 冲突 ${status.conflictCount}</span></div><p>${status.lastSuccessfulSyncAt?'上次成功同步：'+h(new Date(status.lastSuccessfulSyncAt).toLocaleString()):'尚无成功同步记录'}</p>${status.lastErrorCode?`<p role="status">最近同步未完成：${h(status.lastErrorCode)}${status.retryAt?'，下次可重试 '+h(new Date(status.retryAt).toLocaleString()):''}</p>`:''}<div class="setting-inline">${status.enabled?`<button class="primary" type="button" data-sync="run">立即同步</button><button type="button" data-sync="${status.paused?'resume':'pause'}">${status.paused?'继续同步':'暂停同步'}</button><button type="button" data-sync="operations">同步详情</button><button type="button" data-sync="conflicts">冲突中心</button><button type="button" data-sync="retry">失败重试</button>`:'<button type="button" data-sync="preview">首次同步预览</button><button class="primary" type="button" data-sync="enable">预览并确认同步</button>'}</div></section>`:`
   <section data-sync-login-form><h4>登录坚果云</h4><div class="model-form"><label>账号邮箱<input type="email" name="account" value="${h(status.account)}" autocomplete="username"></label><label>第三方应用密码<input name="password" type="password" autocomplete="new-password" placeholder="${status.credentialAvailable?'已安全保存，可留空':'填写坚果云第三方应用密码'}"></label></div><p class="muted">应用密码在坚果云“账户信息 → 安全选项 → 第三方应用管理”中创建。</p><details><summary>同步目录与设备</summary><div class="model-form"><label>接口地址<input name="endpoint" value="${h(status.endpoint)}"></label><label>远程根目录<input name="remoteRoot" value="${h(status.remoteRoot||'/神思同步/')}"></label><label>设备名称<input name="deviceName" value="${h(status.deviceName||'Windows 电脑')}"></label></div></details><label class="setting-inline"><input type="checkbox" data-sync-remember checked>在本机安全保存登录凭据</label><div class="setting-inline"><button type="button" data-sync="test">测试连接</button><button class="primary" type="button" data-sync="configure">登录</button><button type="button" data-sync="preview" ${status.credentialAvailable?'':'disabled'}>首次同步预览</button><button type="button" data-sync="enable" disabled>确认并启用同步</button>${status.account?'<button type="button" data-sync="switch">更换账号</button>':''}</div></section>`}
   <label class="setting-inline"><input type="checkbox" data-sync-auto ${status.autoSync?'checked':''} ${!automatic?'disabled':''}>自动同步</label><p class="muted" data-sync-auto-note>${automatic?'自动同步可随时关闭。网络异常不影响本地保存。':status.capabilityLevel==='safe_manual'?'此连接目前通过手动同步验证；服务器缺少安全条件替换能力，暂不能开启自动同步。':'登录后按服务器实际能力开放自动同步。'}</p>${capabilityHtml(status.capability)}<div data-sync-result role="status" aria-live="polite"></div></section>`;
  if(loggedIn&&notebookApi){const button=document.createElement('button');button.type='button';button.textContent='手机与电脑笔记本传输';button.onclick=()=>openNutstoreNotebooks({api:notebookApi,changed,canResolve}).catch(error=>toast?.(error.message));q('[data-sync-connected]').append(button);}
  if(!loggedIn&&!status.account){
   const details=q('[data-sync-login-form] details'),label=document.createElement('label');label.textContent='同步格式';
   const select=document.createElement('select');select.name='storageProtocol';
   for(const [value,text] of [['legacy-v1','原目录兼容模式'],['journal-v2','安全历史模式（独立新目录）']])select.add(new Option(text,value));
   select.value=status.storageProtocol||'legacy-v1';label.append(select);details.append(label);
   const note=document.createElement('p');note.className='muted';note.textContent='安全历史模式支持不依赖覆盖条件的自动同步。需要独立目录，不会迁移或清空旧目录、基线与冲突；已有连接不能直接切换格式。';details.append(note);
  }
 }
 function values(){return Object.fromEntries([...root.querySelectorAll('[name]')].map(el=>[el.name,el.value]));}
 function showPreview(result){
  previewToken=result.previewToken;q('[data-sync=enable]').disabled=false;q('[data-sync=enable]').textContent='确认并启用同步';
  q('[data-sync-result]').innerHTML=`<h4>首次同步预览</h4><p>上传 ${result.summary.upload} · 下载 ${result.summary.download} · 冲突 ${result.summary.conflict} · 删除 ${result.summary.delete}</p><div class="sync-files">${result.items.map(item=>`<p>${h(item.action)} · ${h(item.logicalPath)}</p>`).join('')}</div><p>核对后点击“确认并启用同步”。</p>`;
 }
 root.oninput=event=>{if(!event.target.matches('[name]'))return;previewToken='';const button=q('[data-sync=enable]');if(button)button.textContent='预览并确认同步';};
 root.onchange=async event=>{
  if(!event.target.matches('[data-sync-auto]')||!q('[data-sync-connected]'))return;
  const checkbox=event.target,requested=checkbox.checked;
  if(busy){checkbox.checked=!requested;return;}if(!currentStatus?.enabled)return;busy=true;checkbox.disabled=true;
  try{await api('auto',{autoSync:requested});}catch(error){checkbox.checked=!requested;toast?.(error.message);}finally{busy=false;if(checkbox.isConnected)checkbox.disabled=false;}
 };
 root.onclick=async event=>{
  const button=event.target.closest('[data-sync],[data-resolve]');if(!button)return;
  if(button.dataset.sync==='operations'){openNutstoreProgress({api,owner:root});return;}
  if(button.dataset.sync==='conflicts'){openNutstoreConflicts({api,changed,canResolve,historyEnabled:true});return;}
  if(busy)return;
  busy=true;button.disabled=true;const out=q('[data-sync-result]');out.textContent=['preview','enable'].includes(button.dataset.sync)?'正在核对同步目录，请稍候…':'正在处理…';
  try{
   const action=button.dataset.sync;
   if(['disconnect','switch'].includes(action)){
    const answer=await modal(action==='disconnect'?'退出坚果云登录？':'更换坚果云账号？','<p>保留本地和云端资料，停止当前自动同步。更换账号会隔离当前同步基线。</p>',[['取消','cancel'],['确认','ok']]);
    if(answer.value!=='ok'){out.textContent='';return;}
   }
   const input={...values(),previewToken,autoSync:q('[data-sync-auto]').checked,remember:q('[data-sync-remember]')?.checked!==false};
   if(button.dataset.resolve){await api('resolve',{conflictId:button.dataset.conflict,resolution:button.dataset.resolve});await render();return;}
   if(action==='enable'&&!previewToken){showPreview(await api('preview',input));return;}
   if(['run','resume','retry','enable'].includes(action))openNutstoreProgress({api,owner:root});
   const result=await api(action,input);
   if(action==='configure'){
    q('[name=password]').value='';await render();q('[data-sync=enable]').disabled=true;
    q('[data-sync-result]').textContent='已登录，正在读取首次同步预览…';showPreview(await api('preview'));
   }else if(action==='preview')showPreview(result);
   else if(action==='test'){if(q('[data-sync-connected]'))await render();q('[data-sync-result]').innerHTML=`<p>${result.ok?'连接测试通过 · '+(result.capability?.capabilityLevel==='safe_auto'?'通过自动同步服务端能力检测':'支持手动同步；当前服务器未满足安全自动同步条件'):'连接未通过验证'}</p>${capabilityHtml(result.capability)}`;}
   else if(action==='conflicts')out.innerHTML='<h4>冲突中心</h4>'+(result.length?result.map(item=>`<section class="setting-block"><strong>${h(item.logicalPath)}</strong><p>${h(item.reason||'本地与云端均有修改')}</p><div class="setting-inline">${[['use_remote','采用云端'],['use_local','采用本地']].map(([key,label])=>`<button type="button" data-resolve="${key}" data-conflict="${h(item.id)}">${label}</button>`).join('')}</div></section>`).join(''):'<p>没有未解决的冲突。</p>');
   else{if(action==='enable'&&input.autoSync)await api('auto',{autoSync:true});if(['enable','run','resume','retry'].includes(action))await changed?.();await render();}
  }catch(error){const target=q('[data-sync-result]');if(target)target.textContent=error.message;previewToken='';const confirm=q('[data-sync=enable]');if(confirm){confirm.disabled=false;confirm.textContent='重新预览并确认同步';}toast?.(error.message);}
  finally{busy=false;if(button.isConnected)button.disabled=false;}
 };
 await render();
}
